process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const A=Buffer.from('','base64').toString();
const B=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/a.html', A); fs.writeFileSync('/tmp/b.html', B);
  const br=await chromium.launch();
  const ctx=await br.newContext({viewport:{width:1400,height:1300}});

  let p=await ctx.newPage();
  await p.goto('file:///tmp/a.html',{waitUntil:'networkidle'});
  await p.waitForTimeout(600);
  await p.selectOption('#kat','maistas'); await p.waitForTimeout(300);
  await p.click('#b-toliau'); await p.waitForTimeout(500);
  await p.click('text=Įdėti pavyzdį'); await p.waitForTimeout(300);
  await p.click('text=Išskaidyti'); await p.waitForTimeout(1200);
  /* matuojam kontrasta */
  out.spalvos=await p.evaluate(()=>{
    const g=(sel)=>{ const e=document.querySelector(sel); return e?getComputedStyle(e).color:null; };
    return { etikete:g('.laukas label'), pastaba:g('.pastaba'), sml:g('.sml'),
             blk_antr:g('.blk-antr'), siul_pav:g('.siul-h .pav') };
  });
  await p.screenshot({path:'/tmp/t_np.png',fullPage:true});
  await p.close();

  p=await ctx.newPage();
  await p.goto('file:///tmp/b.html',{waitUntil:'networkidle'});
  await p.waitForTimeout(700);
  await p.screenshot({path:'/tmp/t_kort.png',fullPage:true});
  await p.close();

  await br.close();
  for(const f of ['t_np','t_kort']){ try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){} }
  await put('analize/tamsu.json', Buffer.from(JSON.stringify(out,null,2)),'t');
}
main().catch(async e=>{ await put('analize/tamsu.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
